+             export function Generic<T extends string>(props: { value: T; extra?: Augmented }) { return null; }\n",
+        )
+        .unwrap();
+        std::fs::write(root.join("Ambient.ts"), "export interface Augmented { own?: number }\n").unwrap();
+        std::fs::write(
